mapper.select:
SELECT id FROM recipes WHERE group_id = #{groupId}

    AND id = #{id}
    AND slug = #{slug}

mapper.update:
UPDATE users_to_recipes
SET rating = #{rating, jdbcType=DOUBLE}, is_favorite = #{favorite}, update_at = #{now}
WHERE id = #{id} AND user_id = #{userId} AND recipe_id = #{recipeId}

UPDATE recipes
SET rating = (SELECT avg(rating) FROM users_to_recipes WHERE recipe_id = #{recipeId} AND rating > 0),
    update_at = #{now}
WHERE id = #{recipeId} AND group_id = #{groupId}
